    /// A TIDAL mock that plays one track and records the bearer token of every manifest request.
    async fn tidal_mock_recording_tokens(flac: Vec<u8>) -> (String, Arc<std::sync::Mutex<Vec<String>>>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
        let seen = Arc::new(std::sync::Mutex::new(Vec::new()));
        let manifest_base = base.clone();
        let seen2 = seen.clone();
        let mock = Router::new()
            .route(
                "/trackManifests/{id}",
                get(move |Path(id): Path<String>, headers: HeaderMap| {
                    let manifest_base = manifest_base.clone();
                    let seen = seen2.clone();
                    async move {
                        let auth = headers.get("authorization").unwrap().to_str().unwrap().to_string();
                        seen.lock().unwrap().push(auth);
                        Json(serde_json::json!({"data": {"id": id, "type": "trackManifests", "attributes": {
                            "uri": format!("{manifest_base}/hls/master.m3u8"), "formats": ["FLAC"], "trackPresentation": "FULL", "hash": "h"}}}))
                    }
                }),
            )
            .route("/hls/master.m3u8", get(|| async { "#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=1000000\nmedia.m3u8\n" }))
            .route("/hls/media.m3u8", get(|| async { "#EXTM3U\n#EXT-X-PLAYLIST-TYPE:VOD\n#EXTINF:1.0,\nseg/0\n#EXT-X-ENDLIST\n" }))
            .route(
                "/hls/seg/{n}",
                get(move |Path(_n): Path<usize>| {
                    let flac = flac.clone();
                    async move { ([(header::CONTENT_TYPE, "application/octet-stream")], flac) }
                }),
            );
        tokio::spawn(async move { axum::serve(listener, mock).await.unwrap() });
        (base, seen)
    }

    /// Each person plays TIDAL with their own account, never anyone else's
    /// (TASK-per-person-service-accounts): the owner's items with the owner's token, a listener's
    /// with theirs, in the same zone; a listener without TIDAL gets "Connect TIDAL" and TIDAL is
    /// never asked with someone else's token. The browser proxy does the same.
    #[tokio::test]
    async fn each_person_plays_tidal_with_their_own_account() {
        let flac = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../pm-audio/tests/fixtures/60_mono_audio.flac"
        ))
        .unwrap();
        let (base, seen) = tidal_mock_recording_tokens(flac).await;
        let dir = tempfile::tempdir().unwrap();
        let s = state(dir.path(), Some("s3cret")).await;
        {
            let mut ep = s.tidal.write().unwrap();
            ep.api_base = base.clone();
            ep.auth_base = base.clone();
            ep.creds = tidal::TidalCredentials {
                client_id: "cid".into(),
                client_secret: "sec".into(),
                scopes: String::new(),
            };
        }
        let session = |token: &str| {
            serde_json::json!({"access_token": token, "refresh_token": "r", "expires_at": pm_library::db::now_unix() + 3600, "user_id": "1", "scope": "playback"}).to_string()
        };
        let (anna, ben) = (
            "tbepfp8fisyiqpskbmxsmpub47gxb7xdsh5x9ut9qrb97gcq9phy",
            "o4dksfbqk85ogzdb5osziw6befigbuxmuxkuxq8434q89uj56uyy",
        );
        {
            let lib = s.library.lock().unwrap();
            lib.set_setting("tidal.user", &session("owner-token")).unwrap();
            lib.set_setting(&format!("person.{anna}.tidal.user"), &session("anna-token"))
                .unwrap();
            lib.set_setting(
                "people",
                &serde_json::json!({"people": [
                {"key": anna, "access": "music", "music_enabled": true, "added_at": 1},
                {"key": ben, "access": "music", "music_enabled": true, "added_at": 1}]})
                .to_string(),
            )
            .unwrap();
        }
        let (anna_tok, ben_tok) = (
            accounts::mint(&s, anna).unwrap(),
            accounts::mint(&s, ben).unwrap(),
        );
        let app = router(s.clone());
        let send = |method: &'static str, uri: String, token: String, body: Option<serde_json::Value>| {
            let app = app.clone();
            async move {
                let req = Request::builder()
                    .method(method)
                    .uri(uri)
                    .header("authorization", format!("Bearer {token}"))
                    .header("content-type", "application/json")
                    .body(
                        body.map(|b| Body::from(b.to_string()))
                            .unwrap_or_else(Body::empty),
                    )
                    .unwrap();
                let r = app.oneshot(req).await.unwrap();
                let st = r.status();
                let b = r.into_body().collect().await.unwrap().to_bytes();
                (
                    st,
                    serde_json::from_slice::<serde_json::Value>(&b).unwrap_or_default(),
                    b,
                )
            }
        };
        let zones = s.zones.list();
        let zid = zones[0].id.to_string();
        let zone = s.zones.get(&ZoneId::new(&zid)).unwrap();
        // One person's item at a time; each plays to its end (or fails)
        let play = |token: String, by_in_body: Option<&'static str>| {
            let send = &send;
            let zone = zone.clone();
            let zid = zid.clone();
            async move {
                let mut item = serde_json::json!({"uri": "tidal:track:20115564"});
                if let Some(b) = by_in_body {
                    // What a client says about who queued it is never believed
                    item["by"] = b.into();
                }
                let (st, v, _) = send(
                    "POST",
                    format!("/v1/zones/{zid}/queue"),
                    token,
                    Some(serde_json::json!({"items": [item], "replace": true, "play": true})),
                )
                .await;
                assert_eq!(st, StatusCode::OK, "{v}");
                zone.wait_stopped().await
            }
        };
        let st = play("s3cret".into(), None).await;
        assert!(st.error.is_none(), "{:?}", st.error);
        let st = play(anna_tok.clone(), None).await;
        assert!(st.error.is_none(), "{:?}", st.error);
        assert_eq!(
            *seen.lock().unwrap(),
            ["Bearer owner-token", "Bearer anna-token"],
            "each item with its queuer's account"
        );
        // Ben has no TIDAL: no fallback to the owner's (nor Anna's), even claiming to be them
        let st = play(ben_tok.clone(), Some(anna)).await;
        assert!(
            st.error.as_deref().is_some_and(|e| e.contains("Connect TIDAL")),
            "{:?}",
            st.error
        );
        let st = play(anna_tok.clone(), Some("")).await;
        assert!(st.error.is_none(), "{:?}", st.error);
        assert_eq!(seen.lock().unwrap().len(), 3, "{:?}", seen.lock().unwrap());
        assert_eq!(seen.lock().unwrap()[2], "Bearer anna-token");

        // The browser proxy: each with their own, Ben refused with the same words
        let (st, _, body) = send(
            "GET",
            "/v1/sources/tidal/stream/20115564".into(),
            anna_tok.clone(),
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK);
        assert!(!body.is_empty());
        assert_eq!(seen.lock().unwrap().last().unwrap(), "Bearer anna-token");
        let n = seen.lock().unwrap().len();
        let (st, v, _) = send(
            "GET",
            "/v1/sources/tidal/stream/20115564".into(),
            ben_tok.clone(),
            None,
        )
        .await;
        assert_eq!(st, StatusCode::PRECONDITION_FAILED, "{v}");
        assert!(v["error"].as_str().unwrap().contains("Connect TIDAL"), "{v}");
        assert_eq!(seen.lock().unwrap().len(), n, "TIDAL never asked for Ben");
        // Each sees their own sign-in, and can't change the node's device client
        let (_, me, _) = send("GET", "/v1/sources/tidal/status".into(), anna_tok.clone(), None).await;
        assert_eq!(me["signed_in"], true, "{me}");
        let (_, me, _) = send("GET", "/v1/sources/tidal/status".into(), ben_tok.clone(), None).await;
        assert_eq!(me["signed_in"], false, "{me}");
        let (st, _, _) = send(
            "PUT",
            "/v1/sources/tidal/unofficial".into(),
            ben_tok.clone(),
            Some(serde_json::json!({"client_id": "x", "client_secret": "y"})),
        )
        .await;
        assert_eq!(st, StatusCode::FORBIDDEN);
        // Ben signing out touches nothing of anyone else's
        let (st, _, _) = send(
            "DELETE",
            "/v1/sources/tidal/session".into(),
            ben_tok.clone(),
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK);
        let lib = s.library.lock().unwrap();
        assert!(lib.get_setting("tidal.user").unwrap().is_some());
        assert!(lib
            .get_setting(&format!("person.{anna}.tidal.user"))
            .unwrap()
            .is_some());
    }

    /// A node with TIDAL against `base`, the owner signed in as `owner-token`, and listeners
    /// Anna (signed in as `anna-token`) and Ben (no TIDAL).
    async fn two_people_node(
        dir: &std::path::Path,
        base: &str,
    ) -> (Arc<NodeState>, &'static str, &'static str) {
        let s = state(dir, Some("s3cret")).await;
        {
            let mut ep = s.tidal.write().unwrap();
            ep.api_base = base.to_string();
            ep.auth_base = base.to_string();
            ep.creds = tidal::TidalCredentials {
                client_id: "cid".into(),
                client_secret: "sec".into(),
                scopes: String::new(),
            };
        }
        let session = |token: &str| {
            serde_json::json!({"access_token": token, "refresh_token": "r", "expires_at": pm_library::db::now_unix() + 3600, "user_id": "1", "scope": "playback"}).to_string()
        };
        let (anna, ben) = (
            "tbepfp8fisyiqpskbmxsmpub47gxb7xdsh5x9ut9qrb97gcq9phy",
            "o4dksfbqk85ogzdb5osziw6befigbuxmuxkuxq8434q89uj56uyy",
        );
        let lib = s.library.lock().unwrap();
        lib.set_setting("tidal.user", &session("owner-token")).unwrap();
        lib.set_setting(&format!("person.{anna}.tidal.user"), &session("anna-token"))
            .unwrap();
        lib.set_setting(
            "people",
            &serde_json::json!({"people": [
            {"key": anna, "access": "music", "music_enabled": true, "added_at": 1},
            {"key": ben, "access": "music", "music_enabled": true, "added_at": 1}]})
            .to_string(),
        )
        .unwrap();
        drop(lib);
        (s, anna, ben)
    }

    /// Moving a queue into a listen-along group (or any zone, `load_zone`) keeps who queued each
    /// item: the host's songs play with the host's account, a joiner's with theirs.
    #[tokio::test]
    async fn a_moved_queue_keeps_who_queued_each_item() {
        let flac = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../pm-audio/tests/fixtures/60_mono_audio.flac"
        ))
        .unwrap();
        let (base, seen) = tidal_mock_recording_tokens(flac).await;
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, _) = two_people_node(dir.path(), &base).await;
        let zid = s.zones.list()[0].id.clone();
        let zone = s.zones.get(&zid).unwrap();
        let mut theirs = QueueItem::new("tidal:track:2");
        theirs.by = Some(anna.into());
        theirs.limit = Some(pm_zones::FetchLimit::PUBLIC);
        let queue = vec![QueueItem::new("tidal:track:1"), theirs];
        load_zone(
            &zone,
            queue,
            Some(0),
            0,
            pm_zones::Transport::Playing,
            pm_zones::Repeat::Off,
            LoadShuffle::Off,
            false,
        )
        .await;
        assert_eq!(zone.queue()[1].by.as_deref(), Some(anna));
        let st = zone.wait_stopped().await;
        assert!(st.error.is_none(), "{:?}", st.error);
        assert_eq!(*seen.lock().unwrap(), ["Bearer owner-token", "Bearer anna-token"]);
    }

    #[tokio::test]
    async fn personal_play_order_http_writes_never_change_another_person() {
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let app = router(s.clone());
        let a = accounts::mint(&s, anna).unwrap();
        let b = accounts::mint(&s, ben).unwrap();
        s.library
            .lock()
            .unwrap()
            .set_setting("play.provider_order", r#"["spotify"]"#)
            .unwrap();
        let send = |method: &str, uri: &str, token: &str, body: serde_json::Value| {
            let app = app.clone();
            let req = Request::builder()
                .method(method)
                .uri(uri)
                .header("authorization", format!("Bearer {token}"))
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .unwrap();
            async move {
                let r = app.oneshot(req).await.unwrap();
                let st = r.status();
                let bytes = r.into_body().collect().await.unwrap().to_bytes();
                (st, serde_json::from_slice::<serde_json::Value>(&bytes).unwrap())
            }
        };
        let (st, v) = send(
            "PUT",
            "/v1/play-order",
            &a,
            serde_json::json!({"order":["tidal"]}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{v}");
        assert_eq!(v["order"][0], "tidal");
        let (st, v) = send(
            "PUT",
            "/v1/play-order",
            &b,
            serde_json::json!({"order":["jamendo"]}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{v}");
        assert_eq!(v["order"][0], "jamendo");
        let (_, v) = send("GET", "/v1/play-order", &a, serde_json::json!(null)).await;
        assert_eq!(v["order"][0], "tidal");
        let (_, v) = send("GET", "/v1/play-order", "s3cret", serde_json::json!(null)).await;
        assert_eq!(v["order"][0], "spotify", "only owner retains legacy default");
        let (_, v) = send("GET", "/v1/me/prefs", &a, serde_json::json!(null)).await;
        assert_eq!(v["play_order"]["value"][0], "tidal");
        let (st, _) = send(
            "PUT",
            "/v1/me/prefs",
            &a,
            serde_json::json!({"play_order":["unknown"]}),
        )
        .await;
        assert_eq!(st, StatusCode::BAD_REQUEST);
        let (_, v) = send("GET", "/v1/play-order", &a, serde_json::json!(null)).await;
        assert_eq!(v["order"][0], "tidal", "invalid update is non-destructive");
        let (st, _) = send("PUT", "/v1/me/prefs", &a, serde_json::json!({"play_order":null})).await;
        assert_eq!(st, StatusCode::OK);
        let (_, v) = send("GET", "/v1/play-order", &a, serde_json::json!(null)).await;
        assert_eq!(
            v["order"][0], "library",
            "listener reset never borrows legacy owner order"
        );
        let (_, v) = send("GET", "/v1/play-order", &b, serde_json::json!(null)).await;
        assert_eq!(v["order"][0], "jamendo");
        assert_eq!(
            s.library
                .lock()
                .unwrap()
                .get_setting("play.provider_order")
                .unwrap()
                .unwrap(),
            r#"["spotify"]"#
        );
    }

    /// Settings › You › Services: each person sees their own sign-ins.
    #[tokio::test]
    async fn me_services_are_the_callers_own() {
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let app = router(s.clone());
        let get = |token: String| {
            let app = app.clone();
            async move {
                let r = app
                    .oneshot(
                        Request::builder()
                            .uri("/v1/me/services")
                            .header("authorization", format!("Bearer {token}"))
                            .body(Body::empty())
                            .unwrap(),
                    )
                    .await
                    .unwrap();
                let st = r.status();
                let b = r.into_body().collect().await.unwrap().to_bytes();
                (
                    st,
                    serde_json::from_slice::<serde_json::Value>(&b).unwrap_or_default(),
                )
            }
        };
        let tidal_of = |v: &serde_json::Value| {
            v.as_array()
                .unwrap()
                .iter()
                .find(|x| x["source"] == "tidal")
                .unwrap()
                .clone()
        };
        let (st, owner) = get("s3cret".into()).await;
        assert_eq!(st, StatusCode::OK, "{owner}");
        assert_eq!(tidal_of(&owner)["connected"], true);
        let (_, a) = get(accounts::mint(&s, anna).unwrap()).await;
        assert_eq!(tidal_of(&a)["connected"], true, "{a}");
        let (_, b) = get(accounts::mint(&s, ben).unwrap()).await;
        assert_eq!(tidal_of(&b)["connected"], false, "{b}");
        assert_eq!(tidal_of(&b)["setup"], "/v1/sources/tidal/signin");
    }

    /// Removing a listener (People) deletes what the node keeps for them: their own sign-ins,
    /// their tokens and their preferences; the owner's and other people's stay.
    #[tokio::test]
    async fn removing_a_listener_deletes_their_sign_ins() {
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let tok = accounts::mint(&s, anna).unwrap();
        s.library
            .lock()
            .unwrap()
            .set_setting(&format!("me.prefs.{anna}"), "{}")
            .unwrap();
        let app = router(s.clone());
        let send = |method: &'static str, uri: String, token: String| {
            let app = app.clone();
            async move {
                app.oneshot(
                    Request::builder()
                        .method(method)
                        .uri(uri)
                        .header("authorization", format!("Bearer {token}"))
                        .body(Body::empty())
                        .unwrap(),
                )
                .await
                .unwrap()
                .status()
            }
        };
        assert_eq!(send("GET", "/v1/me".into(), tok.clone()).await, StatusCode::OK);
        assert_eq!(
            send("DELETE", format!("/v1/people/{anna}"), "s3cret".into()).await,
            StatusCode::OK
        );
        assert_eq!(send("GET", "/v1/me".into(), tok).await, StatusCode::UNAUTHORIZED);
        let lib = s.library.lock().unwrap();
        assert!(lib
            .settings_with_prefix(&format!("person.{anna}."))
            .unwrap()
            .is_empty());
        assert!(lib.get_setting(&format!("me.prefs.{anna}")).unwrap().is_none());
        assert!(
            lib.get_setting("tidal.user").unwrap().is_some(),
            "the owner's stays"
        );
        assert!(!lib.get_setting("people").unwrap().unwrap().contains(anna));
        assert!(lib.get_setting("people").unwrap().unwrap().contains(ben));
    }

    /// A listener's sign-in goes into a backup only sealed under its passphrase, as the owner's.
    #[tokio::test]
    async fn listeners_sign_ins_are_only_in_a_sealed_backup() {
        let dir = tempfile::tempdir().unwrap();
        let (s, _, _) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let has = |hay: &[u8], needle: &str| hay.windows(needle.len()).any(|w| w == needle.as_bytes());
        let (open, _) = backup::make(&s, None).unwrap();
        let open = backup::parse(&open).unwrap();
        assert!(
            !has(&open.database, "anna-token"),
            "a listener's token in a plain backup"
        );
        assert!(
            open.manifest.left_out.iter().any(|w| w.contains("listeners")),
            "{:?}",
            open.manifest.left_out
        );
        let (locked, _) = backup::make(&s, Some("correct horse")).unwrap();
        let locked = backup::parse(&locked).unwrap();
        assert!(!has(&locked.database, "anna-token"));
        // The sealed part holds Anna's own sign-in, under her key
        let sealed = backup::open_sealed(
            locked.manifest.secrets.as_ref().unwrap(),
            locked.secrets.as_ref().unwrap(),
            "correct horse",
        )
        .unwrap();
        let row = sealed
            .settings
            .iter()
            .find(|(k, _)| k.starts_with("person.") && k.ends_with(".tidal.user"))
            .map(|(_, v)| v.clone())
            .unwrap_or_default();
        assert!(
            row.contains("anna-token"),
            "{:?}",
            sealed.settings.keys().collect::<Vec<_>>()
        );
    }

    /// Qobuz plays each person's items with their own sign-in too: the owner's token for the
    /// owner, a listener's for theirs, and "Connect Qobuz" for someone without one.
    #[tokio::test(flavor = "multi_thread")]
    async fn each_person_plays_qobuz_with_their_own_account() {
        let _api_guard = qobuz::API_TEST_LOCK.lock().await;
        let flac = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../pm-audio/tests/fixtures/60_mono_audio.flac"
        ))
        .unwrap();
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
        let seen = Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let (seen2, file_base) = (seen.clone(), base.clone());
        let mock = Router::new()
            .route(
                "/track/getFileUrl",
                get(move |headers: HeaderMap| {
                    let (seen, base) = (seen2.clone(), file_base.clone());
                    async move {
                        let t = headers.get("x-user-auth-token").unwrap().to_str().unwrap().to_string();
                        seen.lock().unwrap().push(t);
                        Json(serde_json::json!({"url": format!("{base}/file.flac"), "format_id": 27, "mime_type": "audio/flac"}))
                    }
                }),
            )
            .route("/file.flac", get(move || { let f = flac.clone(); async move { f } }));
        tokio::spawn(async move { axum::serve(listener, mock).await.unwrap() });
        qobuz::set_api_base(&base);
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let mode = |token: &str| {
            serde_json::json!({"enabled": true, "quality": "max", "session": {"token": token, "hires": true}})
                .to_string()
        };
        {
            let lib = s.library.lock().unwrap();
            lib.set_setting(
                qobuz::APP_KEY,
                r#"{"id": "100000000", "secret": "s3cret", "from": "settings"}"#,
            )
            .unwrap();
            lib.set_setting(qobuz::STATE_KEY, &mode("t-owner")).unwrap();
            lib.set_setting(&format!("person.{anna}.{}", qobuz::STATE_KEY), &mode("t-anna"))
                .unwrap();
        }
        let lib = s.library.clone();
        let opened = tokio::task::spawn_blocking(move || {
            [
                accounts::Who::Owner,
                accounts::Who::Listener(anna.into()),
                accounts::Who::Listener(ben.into()),
                accounts::Who::Nobody,
            ]
            .map(|who| {
                qobuz::open_track_blocking(&lib, "5966783", &who)
                    .map(drop)
                    .map_err(|e| e.to_string())
            })
        })
        .await
        .unwrap();
        assert!(opened[0].is_ok() && opened[1].is_ok(), "{opened:?}");
        assert!(
            opened[2].as_ref().unwrap_err().contains("Connect Qobuz"),
            "{opened:?}"
        );
        assert!(opened[3].is_err(), "nobody's item plays with no one's account");
        assert_eq!(*seen.lock().unwrap(), ["t-owner", "t-anna"]);
    }

    /// A request with a node token, and its status, JSON body and headers.
    async fn send_as(
        app: &Router,
        method: &str,
        uri: &str,
        token: Option<&str>,
        extra: &[(&str, &str)],
        body: Option<serde_json::Value>,
    ) -> (StatusCode, serde_json::Value, HeaderMap) {
        let mut req = Request::builder()
            .method(method)
            .uri(uri)
            .header("content-type", "application/json");
        if let Some(t) = token {
            req = req.header("authorization", format!("Bearer {t}"));
        }
        for (k, v) in extra {
            req = req.header(*k, *v);
        }
        let r = app
            .clone()
            .oneshot(
                req.body(
                    body.map(|b| Body::from(b.to_string()))
                        .unwrap_or_else(Body::empty),
                )
                .unwrap(),
            )
            .await
            .unwrap();
        let (st, h) = (r.status(), r.headers().clone());
        let b = r.into_body().collect().await.unwrap().to_bytes();
        (st, serde_json::from_slice(&b).unwrap_or_default(), h)
    }

    /// A TIDAL API mock: the token endpoint (`token` for any grant) and `/searchResults`,
    /// recording each search's bearer.
    async fn tidal_auth_and_search_mock(token: &'static str) -> (String, Arc<std::sync::Mutex<Vec<String>>>) {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
        let seen = Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen2 = seen.clone();
        let mock = Router::new()
            .route(
                "/v1/oauth2/token",
                post(move || async move {
                    Json(serde_json::json!({"access_token": token, "refresh_token": "r", "expires_in": 3600, "user_id": 77}))
                }),
            )
            .route(
                "/searchResults",
                get(move |headers: HeaderMap| {
                    let seen = seen2.clone();
                    async move {
                        let b = headers.get("authorization").unwrap().to_str().unwrap().to_string();
                        seen.lock().unwrap().push(b);
                        Json(serde_json::json!({"data": [], "included": []}))
                    }
                }),
            );
        tokio::spawn(async move { axum::serve(listener, mock).await.unwrap() });
        (base, seen)
    }

    /// A listener's search runs in a task of its own per source: it still uses their own TIDAL
    /// sign-in (or the app's), never the owner's (#226 review H1).
    #[tokio::test]
    async fn a_listeners_search_uses_their_own_sign_in() {
        let (base, seen) = tidal_auth_and_search_mock("app-token").await;
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), &base).await;
        let app = router(s.clone());
        let (anna_tok, ben_tok) = (
            accounts::mint(&s, anna).unwrap(),
            accounts::mint(&s, ben).unwrap(),
        );
        let (st, v, _) = send_as(
            &app,
            "GET",
            "/v1/search?q=lucky&scope=tidal",
            Some(&anna_tok),
            &[],
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{v}");
        let mine: Vec<String> = seen.lock().unwrap().drain(..).collect();
        assert!(!mine.is_empty(), "TIDAL was searched");
        assert!(mine.iter().all(|b| b == "Bearer anna-token"), "{mine:?}");
        let (st, _, _) = send_as(
            &app,
            "GET",
            "/v1/search?q=other&scope=tidal",
            Some(&ben_tok),
            &[],
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK);
        let bens: Vec<String> = seen.lock().unwrap().drain(..).collect();
        assert!(
            bens.iter()
                .all(|b| b != "Bearer owner-token" && b != "Bearer anna-token"),
            "Ben searches with the app's token: {bens:?}"
        );
    }

    /// A listener's own TIDAL sign-in in the browser: kept for them, and only when it comes back
    /// to the browser that started it (#226 review M2). The owner approving a listener's sign-in
    /// link binds nothing; removing a listener drops their sign-ins still on the way (L1).
    #[tokio::test]
    async fn a_listeners_browser_sign_in_is_kept_for_them_only_from_their_browser() {
        let (base, _) = tidal_auth_and_search_mock("fresh-token").await;
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), &base).await;
        let app = router(s.clone());
        let (anna_tok, ben_tok) = (
            accounts::mint(&s, anna).unwrap(),
            accounts::mint(&s, ben).unwrap(),
        );
        // Starts a login as `token`: the state and the cookie its browser got
        let start = |token: String| {
            let app = app.clone();
            async move {
                let (st, v, h) =
                    send_as(&app, "GET", "/v1/sources/tidal/login", Some(&token), &[], None).await;
                assert_eq!(st, StatusCode::OK, "{v}");
                let url = url::Url::parse(v["url"].as_str().unwrap()).unwrap();
                let state = url
                    .query_pairs()
                    .find(|(k, _)| k == "state")
                    .unwrap()
                    .1
                    .to_string();
                let cookie = h
                    .get("set-cookie")
                    .map(|c| c.to_str().unwrap().split(';').next().unwrap().to_string());
                (state, cookie)
            }
        };
        let callback = |state: String, cookie: Option<String>| {
            let app = app.clone();
            async move {
                let extra: Vec<(&str, &str)> = cookie.iter().map(|c| ("cookie", c.as_str())).collect();
                let (_, _, h) = send_as(
                    &app,
                    "GET",
                    &format!("/tidal/callback?code=c&state={state}"),
                    None,
                    &extra,
                    None,
                )
                .await;
                h.get("location").unwrap().to_str().unwrap().to_string()
            }
        };
        let row = |key: &str| s.library.lock().unwrap().get_setting(key).unwrap();
        // Anna, in her own browser: hers
        let (state, cookie) = start(anna_tok.clone()).await;
        assert!(cookie.is_some(), "a listener's login is bound to their browser");
        assert_eq!(callback(state, cookie).await, "/?tidal=signed_in");
        assert!(row(&format!("person.{anna}.tidal.user"))
            .unwrap()
            .contains("fresh-token"));
        assert!(
            row("tidal.user").unwrap().contains("owner-token"),
            "the owner's untouched"
        );
        // Ben's link approved in someone else's browser (no cookie), or pasted by the owner: refused
        let (state, _) = start(ben_tok.clone()).await;
        assert!(callback(state, None).await.starts_with("/?tidal=error"));
        let (state, _) = start(ben_tok.clone()).await;
        let pasted = serde_json::json!({"url": format!("http://node/tidal/callback?code=c&state={state}")});
        let (st, _, _) = send_as(
            &app,
            "POST",
            "/v1/sources/tidal/callback",
            Some("s3cret"),
            &[],
            Some(pasted),
        )
        .await;
        assert_eq!(st, StatusCode::BAD_REQUEST);
        assert!(row(&format!("person.{ben}.tidal.user")).is_none());
        // Ben removed while his own sign-in is on the way: it never lands
        let (state, cookie) = start(ben_tok.clone()).await;
        let (st, _, _) = send_as(
            &app,
            "DELETE",
            &format!("/v1/people/{ben}"),
            Some("s3cret"),
            &[],
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK);
        assert!(callback(state, cookie).await.starts_with("/?tidal=error"));
        assert!(row(&format!("person.{ben}.tidal.user")).is_none());
    }

    /// A listener whose music access is switched off (People) plays nothing with their sign-ins,
    /// items they queued before included (L2); the owner taking a queue over from a browser takes
    /// it whole, with no listener's fetch limit left on it (L4).
    #[tokio::test]
    async fn a_blocked_listeners_items_play_with_no_account_and_the_owner_takes_queues_whole() {
        let flac = std::fs::read(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../pm-audio/tests/fixtures/60_mono_audio.flac"
        ))
        .unwrap();
        let (base, seen) = tidal_mock_recording_tokens(flac).await;
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, _) = two_people_node(dir.path(), &base).await;
        let app = router(s.clone());
        let anna_tok = accounts::mint(&s, anna).unwrap();
        let zid = s.zones.list()[0].id.clone();
        let zone = s.zones.get(&zid).unwrap();
        let item =
            serde_json::json!({"items": [{"uri": "tidal:track:20115564"}], "replace": true, "play": false});
        let (st, _, _) = send_as(
            &app,
            "POST",
            &format!("/v1/zones/{zid}/queue"),
            Some(&anna_tok),
            &[],
            Some(item),
        )
        .await;
        assert_eq!(st, StatusCode::OK);
        let off = serde_json::json!({"music": false});
        let (st, v, _) = send_as(
            &app,
            "PATCH",
            &format!("/v1/people/{anna}"),
            Some("s3cret"),
            &[],
            Some(off),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{v}");
        zone.play();
        let st = zone.wait_stopped().await;
        assert!(st.error.is_some(), "Anna's item no longer plays with her account");
        assert!(seen.lock().unwrap().is_empty(), "{:?}", seen.lock().unwrap());

        // The owner moves a browser queue holding a listener's item: theirs now, whole
        let moved = serde_json::json!({"items": [{"uri": "tidal:track:20115564", "by": anna, "limit": {"lan": false}}], "index": 0, "transport": "playing"});
        let (st, v, _) = send_as(
            &app,
            "POST",
            &format!("/v1/zones/{zid}/load"),
            Some("s3cret"),
            &[],
            Some(moved),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{v}");
        let q = zone.queue();
        assert_eq!((q[0].by.as_deref(), q[0].limit), (None, None));
        let st = zone.wait_stopped().await;
        assert!(st.error.is_none(), "{:?}", st.error);
        assert_eq!(*seen.lock().unwrap(), ["Bearer owner-token"]);
    }

    /// A homeserver for the copy jobs' tests: records uploads and deletes; uploads fail while
    /// `fails` is set, keep `short` bytes less than sent, and use up `disk`'s free space.
    #[derive(Default)]
    struct FakeHomeserver {
        uploads: std::sync::Mutex<Vec<String>>,
        deletes: std::sync::Mutex<Vec<String>>,
        sizes: std::sync::Mutex<std::collections::HashMap<String, u64>>,
        fails: std::sync::atomic::AtomicBool,
        short: std::sync::atomic::AtomicU64,
        disk: Option<Arc<FakeDisk>>,
        /// What else each upload uses on the disk (the homeserver's database and logs).
        extra: u64,
        /// What the homeserver lists before the copy.
        listed: std::sync::Mutex<Vec<pm_pubky::homeserver::RemoteFile>>,
        /// Uploads after this many fail, as while `fails` is set.
        fail_after: Option<usize>,
        /// Checking a file's size fails (the homeserver went away after an upload).
        stat_fails: std::sync::atomic::AtomicBool,
        /// Files whose size the homeserver doesn't say (no Content-Length).
        no_size: std::sync::Mutex<std::collections::HashSet<String>>,
        /// How long each upload takes.
        delay: Option<std::time::Duration>,
        /// How long a size check takes.
        stat_delay: Option<std::time::Duration>,
        /// Uploads (`up:`) and deletes (`del:`) in the order they happened.
        ops: std::sync::Mutex<Vec<String>>,
        /// Whose homeserver it is when set (else `fake-account`): a sign-in as someone else.
        who: std::sync::Mutex<Option<String>>,
    }

    #[async_trait::async_trait]
    impl copy_guard::Target for FakeHomeserver {
        async fn list(&self) -> Result<Vec<pm_pubky::homeserver::RemoteFile>, String> {
            Ok(self.listed.lock().unwrap().clone())
        }
        async fn upload(
            &self,
            remote: &str,
            bytes: Vec<u8>,
            _rate: Option<u64>,
        ) -> Result<(), copy_guard::UploadError> {
            if let Some(d) = self.delay {
                tokio::time::sleep(d).await;
            }
            self.ops.lock().unwrap().push(format!("up:{remote}"));
            let n = {
                let mut u = self.uploads.lock().unwrap();
                u.push(remote.to_string());
                u.len()
            };
            if self.fails.load(std::sync::atomic::Ordering::SeqCst) || self.fail_after.is_some_and(|k| n > k)
            {
                // As a homeserver failing mid-write: half the file left there
                self.sizes
                    .lock()
                    .unwrap()
                    .insert(remote.to_string(), bytes.len() as u64 / 2);
                return Err(copy_guard::UploadError::Other("500 Internal Server Error".into()));
            }
            let kept =
                (bytes.len() as u64).saturating_sub(self.short.load(std::sync::atomic::Ordering::SeqCst));
            self.sizes.lock().unwrap().insert(remote.to_string(), kept);
            if let Some(d) = &self.disk {
                let mut sp = d.0.lock().unwrap();
                sp.free = sp.free.saturating_sub(kept + self.extra);
            }
            Ok(())
        }
        async fn stat(&self, remote: &str) -> Result<Option<Option<u64>>, String> {
            if let Some(d) = self.stat_delay {
                tokio::time::sleep(d).await;
            }
            if self.stat_fails.load(std::sync::atomic::Ordering::SeqCst) {
                return Err("connection reset".into());
            }
            let no_size = self.no_size.lock().unwrap().contains(remote);
            Ok(self
                .sizes
                .lock()
                .unwrap()
                .get(remote)
                .map(|n| (!no_size).then_some(*n)))
        }
        async fn delete(&self, remote: &str) -> Result<(), String> {
            self.ops.lock().unwrap().push(format!("del:{remote}"));
            self.deletes.lock().unwrap().push(remote.to_string());
            Ok(())
        }
        fn account(&self) -> String {
            self.who
                .lock()
                .unwrap()
                .clone()
                .unwrap_or_else(|| "fake-account".into())
        }
    }

    /// The bundled homeserver's disk, as the copy jobs see it.
    struct FakeDisk(std::sync::Mutex<copy_guard::Space>);

    impl copy_guard::Room for FakeDisk {
        fn space(&self) -> Option<copy_guard::Space> {
            Some(*self.0.lock().unwrap())
        }
    }

    const GB: u64 = 1 << 30;

    /// A node whose copy jobs go to `hs` on `disk`, and a folder of `n` short songs.
    async fn copy_setup(
        hs: Arc<FakeHomeserver>,
        disk: Arc<FakeDisk>,
        n: u32,
    ) -> (tempfile::TempDir, Arc<NodeState>, Router, std::path::PathBuf) {
        let dir = tempfile::tempdir().unwrap();
        let s = state(dir.path(), None).await;
        *s.copy_seams.lock().unwrap() = (Some(hs), Some(disk));
        let src = dir.path().join("music");
        std::fs::create_dir_all(&src).unwrap();
        for i in 1..=n {
            tone_wav(&src.join(format!("{i:02} song.wav")), 1);
        }
        let app = router(s.clone());
        (dir, s, app, src)
    }

    async fn copy_finished(app: &Router, id: &str) -> serde_json::Value {
        for _ in 0..200 {
            let (_, v) = call(app, "GET", &format!("/v1/pubky/files/upload/{id}"), None).await;
            if v["finished"] == true {
                return v;
            }
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }
        panic!("the copy never finished");
    }

    /// A copy to the bundled homeserver whose disk is 95 % full is refused before anything is
    /// sent (NUC, 2026-11-01: a folder copy filled the disk and took the homeserver's database
    /// down); the dry run shows what it needs against what is free.
    #[tokio::test]
    async fn a_copy_into_the_disks_reserve_is_refused_before_it_starts() {
        let hs = Arc::new(FakeHomeserver::default());
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 98 * GB / 20,
            total: 98 * GB,
        })));
        let (_dir, _s, app, src) = copy_setup(hs.clone(), disk, 2).await;
        let body = |dry: bool| Some(serde_json::json!({"path": src, "dry_run": dry}));
        let (st, dry) = call(&app, "POST", "/v1/library/imports", body(true)).await;
        assert_eq!(st, StatusCode::OK, "{dry}");
        assert_eq!(dry["reserve_bytes"], 5 * GB, "{dry}");
        assert_eq!(dry["free_bytes"], 98 * GB / 20, "{dry}");
        assert!(dry["needed_bytes"].as_u64().unwrap() > 0, "{dry}");
        let (st, e) = call(&app, "POST", "/v1/library/imports", body(false)).await;
        assert_eq!(st, StatusCode::INSUFFICIENT_STORAGE, "{e}");
        assert!(
            e["error"]
                .as_str()
                .unwrap()
                .starts_with("not enough space on this machine"),
            "{e}"
        );
        assert!(hs.uploads.lock().unwrap().is_empty());
    }

    /// Space running low partway: the copy stops before the file that would eat into the
    /// reserve, and says why.
    #[tokio::test]
    async fn a_copy_stops_before_the_disk_reaches_its_reserve() {
        // Room for the three songs (176, 352 and 529 KB) at the start; each upload also uses
        // 800 KB more on the disk, so after the first the second would eat into the reserve
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 5 * GB + 1_100_000,
            total: 98 * GB,
        })));
        let hs = Arc::new(FakeHomeserver {
            disk: Some(disk.clone()),
            extra: 800_000,
            ..Default::default()
        });
        let (_dir, _s, app, src) = copy_setup(hs.clone(), disk, 0).await;
        // Songs that differ: the same content twice in one job is sent once
        for i in 1..=3 {
            tone_wav(&src.join(format!("{i:02} song.wav")), i);
        }
        let (st, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{job}");
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["done"], 1, "{done}");
        assert!(
            done["stopped_reason"]
                .as_str()
                .unwrap()
                .contains("not enough space on this machine"),
            "{done}"
        );
        assert_eq!(hs.uploads.lock().unwrap().len(), 1);
    }

    /// The homeserver failing (500s, as when its disk was full on the NUC) stops the copy after
    /// three failures in a row instead of trying every file; nothing half sent is left there.
    #[tokio::test]
    async fn three_failures_in_a_row_stop_a_copy() {
        let hs = Arc::new(FakeHomeserver::default());
        hs.fails.store(true, std::sync::atomic::Ordering::SeqCst);
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, _s, app, src) = copy_setup(hs.clone(), disk, 6).await;
        let (_, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["failed"], 3, "{done}");
        assert!(
            done["stopped_reason"]
                .as_str()
                .unwrap()
                .contains("3 failures in a row"),
            "{done}"
        );
        let uploads = hs.uploads.lock().unwrap().clone();
        assert_eq!(uploads.len(), 3, "no 4th file is sent");
        assert_eq!(
            *hs.deletes.lock().unwrap(),
            uploads,
            "each failed one is deleted there"
        );
    }

    /// macOS's `._*` AppleDouble files and files that only look like audio are not copied; a
    /// short upload is deleted on the homeserver, never left as a truncated song.
    #[tokio::test]
    async fn only_whole_audio_files_are_copied() {
        let hs = Arc::new(FakeHomeserver::default());
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, _s, app, src) = copy_setup(hs.clone(), disk, 1).await;
        std::fs::write(src.join("._01 song.wav"), vec![0u8; 4096]).unwrap();
        std::fs::write(src.join("02 notes.flac"), b"not audio at all").unwrap();
        // The `._` file isn't counted in the space needed either
        let song = std::fs::metadata(src.join("01 song.wav")).unwrap().len();
        let (_, dry) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src, "dry_run": true})),
        )
        .await;
        assert_eq!(dry["needed_bytes"], song + 16, "{dry}");
        let (_, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(
            (done["done"].clone(), done["not_audio"].clone()),
            (1.into(), 2.into()),
            "{done}"
        );
        let uploads = hs.uploads.lock().unwrap().clone();
        assert_eq!(uploads.len(), 1, "{uploads:?}");
        assert!(uploads[0].ends_with("song.wav"), "{uploads:?}");

        // The homeserver keeps less than was sent: deleted there, counted as failed
        hs.short.store(10, std::sync::atomic::Ordering::SeqCst);
        std::fs::remove_file(src.join("._01 song.wav")).unwrap();
        tone_wav(&src.join("03 other.wav"), 2);
        let (_, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert!(done["failed"].as_u64().unwrap() >= 1, "{done}");
        assert!(
            done["errors"].to_string().contains("the homeserver kept"),
            "{done}"
        );
        let deletes = hs.deletes.lock().unwrap().clone();
        assert!(deletes.iter().any(|d| d.ends_with("other.wav")), "{deletes:?}");
    }

    /// The library copy (`POST /v1/pubky/files/upload`) has the same guards: three failures in a
    /// row stop it, and a disk at 95 % refuses it before it starts.
    #[tokio::test]
    async fn the_library_copy_has_the_same_guards() {
        let hs = Arc::new(FakeHomeserver::default());
        hs.fails.store(true, std::sync::atomic::Ordering::SeqCst);
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk.clone(), 5).await;
        for i in 1..=5 {
            let t = untagged_track(src.join(format!("{i:02} song.wav")), &format!("Song {i}"), "Band");
            s.library.lock().unwrap().upsert_track(&t).unwrap();
        }
        let (st, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        assert_eq!(st, StatusCode::ACCEPTED, "{job}");
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["failed"], 3, "{done}");
        assert!(
            done["stopped_reason"].to_string().contains("3 failures in a row"),
            "{done}"
        );
        assert_eq!(hs.uploads.lock().unwrap().len(), 3);

        *disk.0.lock().unwrap() = copy_guard::Space {
            free: 98 * GB / 20,
            total: 98 * GB,
        };
        let (st, e) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        assert_eq!(st, StatusCode::INSUFFICIENT_STORAGE, "{e}");
    }

    /// The homeserver name a library file is copied to, and its size (its hash remembered as a
    /// copy before would have).
    fn copied_name(s: &NodeState, path: &std::path::Path) -> (String, u64) {
        let bytes = std::fs::read(path).unwrap();
        let hash = blake3::hash(&bytes).to_hex().to_string();
        let m = std::fs::metadata(path).unwrap();
        let mtime = m
            .modified()
            .unwrap()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as i64;
        s.library
            .lock()
            .unwrap()
            .store_file_hash(path, m.len(), mtime, &hash)
            .unwrap();
        (
            format!(
                "{}{}",
                pm_pubky::homeserver::PRIVATE_FILES_DIR,
                files::remote_name_for(&hash, &files::safe_file_name(path))
            ),
            bytes.len() as u64,
        )
    }

    /// A file the homeserver has at another size than the song (its name is the content's hash,
    /// so a broken copy) is sent again; when that fails too, what it left is deleted like any half
    /// written file, never kept as a truncated song (#224 follow-ups, Kimi 4).
    #[tokio::test]
    async fn a_failed_repair_of_a_broken_copy_leaves_nothing_half_written() {
        let hs = Arc::new(FakeHomeserver::default());
        hs.fails.store(true, std::sync::atomic::Ordering::SeqCst);
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk, 1).await;
        let path = src.join("01 song.wav");
        let (remote, len) = copied_name(&s, &path);
        hs.listed.lock().unwrap().push(pm_pubky::homeserver::RemoteFile {
            path: remote.clone(),
            size: None,
        });
        hs.sizes.lock().unwrap().insert(remote.clone(), len / 3);
        let t = untagged_track(path, "Song 1", "Band");
        s.library.lock().unwrap().upsert_track(&t).unwrap();
        let (_, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["failed"], 1, "{done}");
        assert_eq!(
            *hs.uploads.lock().unwrap(),
            std::slice::from_ref(&remote),
            "it was sent again"
        );
        assert_eq!(*hs.deletes.lock().unwrap(), [remote], "the half sent is removed");
    }

    /// An upload a stopped node left in flight (a crash, a restart) is settled at the next start:
    /// one it made that the homeserver keeps at another size is deleted, an empty one included; a
    /// complete one, or a file that was there before, stays. One whose size the homeserver doesn't
    /// say, or that another account made, stays recorded (#224 review; follow-ups Kimi 2 and 5).
    #[tokio::test]
    async fn uploads_a_stopped_node_left_half_written_are_removed_at_start() {
        let hs = Arc::new(FakeHomeserver::default());
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, _app, _src) = copy_setup(hs.clone(), disk, 0).await;
        let f = |n: &str| format!("/priv/pubky.music/files/{n}");
        {
            let mut sizes = hs.sizes.lock().unwrap();
            for (n, size) in [
                ("half", 40),
                ("whole", 70),
                ("before", 10),
                ("empty", 0),
                ("unknown", 0),
                ("elsewhere", 5),
                ("mine", 5),
            ] {
                sizes.insert(f(n), size);
            }
            hs.no_size.lock().unwrap().insert(f("unknown"));
        }
        s.library
            .lock()
            .unwrap()
            .set_setting(
                copy_guard::IN_FLIGHT_KEY,
                &serde_json::json!({
                    f("half"): {"size": 100, "existed": false},
                    f("whole"): {"size": 70, "existed": false},
                    f("before"): {"size": 50, "existed": true},
                    f("empty"): {"size": 30},
                    f("unknown"): {"size": 30, "existed": false},
                    f("elsewhere"): {"size": 30, "account": "someone-else"},
                    f("mine"): {"size": 30, "account": "fake-account"},
                })
                .to_string(),
            )
            .unwrap();
        copy_guard::settle_in_flight(&s, 1, std::time::Duration::ZERO).await;
        let mut deleted = hs.deletes.lock().unwrap().clone();
        deleted.sort();
        assert_eq!(deleted, [f("empty"), f("half"), f("mine")]);
        let left: serde_json::Value = serde_json::from_str(
            &s.library
                .lock()
                .unwrap()
                .get_setting(copy_guard::IN_FLIGHT_KEY)
                .unwrap()
                .unwrap(),
        )
        .unwrap();
        let mut left: Vec<&String> = left.as_object().unwrap().keys().collect();
        left.sort();
        assert_eq!(left, [&f("elsewhere"), &f("unknown")]);
    }

    /// Copying a library mostly there already: only what it sends counts against the disk's
    /// reserve, so running it again isn't refused for the files it skips (#224 review).
    #[tokio::test]
    async fn a_copy_run_again_counts_only_what_it_sends() {
        let hs = Arc::new(FakeHomeserver::default());
        // Room for one more song at most: the two already there would not fit again
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 5 * GB + 200_000,
            total: 98 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk, 2).await;
        for i in 1..=2 {
            let path = src.join(format!("{i:02} song.wav"));
            let (remote, len) = copied_name(&s, &path);
            hs.listed.lock().unwrap().push(pm_pubky::homeserver::RemoteFile {
                path: remote,
                size: Some(len),
            });
            let mut t = untagged_track(path, &format!("Song {i}"), "Band");
            t.file.size_bytes = len;
            s.library.lock().unwrap().upsert_track(&t).unwrap();
        }
        let (st, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        assert_eq!(st, StatusCode::ACCEPTED, "{job}");
        assert_eq!(job["needed_bytes"], 0, "{job}");
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["skipped"], 2, "{done}");
        assert!(hs.uploads.lock().unwrap().is_empty());
    }

    /// A song dropped on the Add music page is refused (507) when it would eat into the reserve
