    /// An import to another homeserver also writes each file into this node's mirror folder:
    /// the reserve that counts is that disk's, not none (#224 review).
    #[tokio::test]
    async fn an_import_to_another_homeserver_keeps_the_nodes_disk_reserve() {
        let dir = tempfile::tempdir().unwrap();
        let s = state(dir.path(), None).await;
        assert!(
            copy_guard::room_of(&s).space().is_none(),
            "no bundled homeserver here"
        );
        assert!(
            copy_guard::room_for_store(&s).space().is_some(),
            "the mirror folder's disk is measured"
        );
    }

    /// The crash settle at start waits for the homeserver session, which the node restores only
    /// after it looked at its jobs (#224 delta review): it runs once the session is there.
    #[tokio::test]
    async fn uploads_left_in_flight_are_settled_once_the_session_arrives() {
        let hs = Arc::new(FakeHomeserver::default());
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, _app, _src) = copy_setup(hs.clone(), disk, 0).await;
        // No session yet
        s.copy_seams.lock().unwrap().0 = None;
        hs.sizes
            .lock()
            .unwrap()
            .insert("/priv/pubky.music/files/half".into(), 40);
        s.library
            .lock()
            .unwrap()
            .set_setting(
                copy_guard::IN_FLIGHT_KEY,
                &serde_json::json!({"/priv/pubky.music/files/half": {"size": 100, "existed": false}})
                    .to_string(),
            )
            .unwrap();
        let s2 = s.clone();
        let settling = tokio::spawn(async move {
            copy_guard::settle_in_flight(&s2, 50, std::time::Duration::from_millis(20)).await
        });
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert!(
            hs.deletes.lock().unwrap().is_empty(),
            "nothing before the session"
        );
        s.copy_seams.lock().unwrap().0 = Some(hs.clone());
        settling.await.unwrap();
        assert_eq!(*hs.deletes.lock().unwrap(), ["/priv/pubky.music/files/half"]);
    }

    /// A folder imported before the node remembered its files' hashes: running the import again
    /// counts what the homeserver lists under the file's name and size as there, so it isn't
    /// refused for the songs it would skip (#224 delta review; the NUC's 82 GB).
    #[tokio::test]
    async fn an_import_run_again_skips_what_was_stored_before_hashes_were_remembered() {
        let hs = Arc::new(FakeHomeserver::default());
        // Room for one more song at most: the two already there would not fit again
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 5 * GB + 200_000,
            total: 98 * GB,
        })));
        let (_dir, _s, app, src) = copy_setup(hs.clone(), disk, 2).await;
        for i in 1..=2 {
            let name = format!("{i:02} song.wav");
            let size = std::fs::metadata(src.join(&name)).unwrap().len();
            hs.listed.lock().unwrap().push(pm_pubky::homeserver::RemoteFile {
                path: format!(
                    "{}0123456789abcde{i}-{}",
                    pm_pubky::homeserver::PRIVATE_FILES_DIR,
                    add_music::safe_name(&name)
                ),
                size: Some(size),
            });
        }
        let (st, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{job}");
        assert_eq!(job["needed_bytes"], 0, "{job}");
    }

    /// The single-file upload (`POST /v1/pubky/files`) keeps the bundled homeserver's reserve too.
    #[tokio::test]
    async fn a_single_file_upload_into_the_disks_reserve_is_refused() {
        let hs = Arc::new(FakeHomeserver::default());
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 98 * GB / 20,
            total: 98 * GB,
        })));
        let (_dir, _s, app, src) = copy_setup(hs, disk, 1).await;
        let (st, e) = call(
            &app,
            "POST",
            "/v1/pubky/files",
            Some(serde_json::json!({"path": src.join("01 song.wav")})),
        )
        .await;
        assert_eq!(st, StatusCode::INSUFFICIENT_STORAGE, "{e}");
    }

    /// A file the homeserver lists without its size is checked before a copy sends over it: the
    /// homeserver has no rename, so a failed upload over the good copy would leave it truncated
    /// (#224 review). Kept when its size is the source's, sent over only when known to differ.
    #[tokio::test]
    async fn a_copy_never_sends_over_a_whole_file_it_could_not_size() {
        let hs = Arc::new(FakeHomeserver::default());
        hs.fails.store(true, std::sync::atomic::Ordering::SeqCst);
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk, 1).await;
        let path = src.join("01 song.wav");
        let (remote, len) = copied_name(&s, &path);
        hs.listed.lock().unwrap().push(pm_pubky::homeserver::RemoteFile {
            path: remote.clone(),
            size: None,
        });
        hs.sizes.lock().unwrap().insert(remote.clone(), len);
        let mut t = untagged_track(path, "Song 1", "Band");
        t.file.size_bytes = len;
        s.library.lock().unwrap().upsert_track(&t).unwrap();
        let (_, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(done["skipped"], 1, "{done}");
        assert!(hs.uploads.lock().unwrap().is_empty(), "sent over the good copy");
        assert_eq!(hs.sizes.lock().unwrap()[&remote], len);
    }

    /// Two files of one job under the same homeserver name: the second isn't sent again, so its
    /// failure can never delete the first's good copy (#224 review). The library copy and an
    /// import both.
    #[tokio::test]
    async fn a_second_file_of_a_job_with_the_same_name_leaves_the_first_alone() {
        let hs = Arc::new(FakeHomeserver {
            fail_after: Some(1),
            ..Default::default()
        });
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk, 0).await;
        for d in ["a", "b"] {
            std::fs::create_dir_all(src.join(d)).unwrap();
            tone_wav(&src.join(d).join("01 song.wav"), 1);
            let t = untagged_track(src.join(d).join("01 song.wav"), "Song 1", "Band");
            s.library.lock().unwrap().upsert_track(&t).unwrap();
        }
        let (_, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(
            (done["done"].clone(), done["skipped"].clone()),
            (1.into(), 1.into()),
            "{done}"
        );
        assert_eq!(hs.uploads.lock().unwrap().len(), 1);
        assert!(hs.deletes.lock().unwrap().is_empty());

        hs.uploads.lock().unwrap().clear();
        hs.sizes.lock().unwrap().clear();
        let (_, job) = call(
            &app,
            "POST",
            "/v1/library/imports",
            Some(serde_json::json!({"path": src})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(
            (done["done"].clone(), done["skipped"].clone()),
            (1.into(), 1.into()),
            "{done}"
        );
        assert!(hs.deletes.lock().unwrap().is_empty());
    }

    /// When the homeserver can't be asked what it kept after an upload, the file counts as failed
    /// and its in-flight record stays for the next start to settle (#224 review).
    #[tokio::test]
    async fn an_upload_whose_size_cant_be_checked_is_failed_and_kept_in_flight() {
        let hs = Arc::new(FakeHomeserver::default());
        hs.stat_fails.store(true, std::sync::atomic::Ordering::SeqCst);
        let disk = Arc::new(FakeDisk(std::sync::Mutex::new(copy_guard::Space {
            free: 500 * GB,
            total: 1000 * GB,
        })));
        let (_dir, s, app, src) = copy_setup(hs.clone(), disk, 1).await;
        let path = src.join("01 song.wav");
        let (remote, _) = copied_name(&s, &path);
        let t = untagged_track(path, "Song 1", "Band");
        s.library.lock().unwrap().upsert_track(&t).unwrap();
        let (_, job) = call(
            &app,
            "POST",
            "/v1/pubky/files/upload",
            Some(serde_json::json!({"all": true})),
        )
        .await;
        let done = copy_finished(&app, job["id"].as_str().unwrap()).await;
        assert_eq!(
            (done["done"].clone(), done["failed"].clone()),
            (0.into(), 1.into()),
            "{done}"
        );
        let flight = s
            .library
            .lock()
            .unwrap()
            .get_setting(copy_guard::IN_FLIGHT_KEY)
            .unwrap()
            .unwrap_or_default();
        assert!(flight.contains(&remote), "{flight}");
    }

    /// A TIDAL device sign-in whose approval arrives after its person signed out, or after a
    /// listener was removed, is not kept: no sign-in comes back for them (per-person follow-up,
    /// Kimi M1).
    #[tokio::test]
    async fn a_sign_in_answered_after_sign_out_or_removal_is_not_kept() {
        let asked = Arc::new(std::sync::atomic::AtomicU32::new(0));
        let go = Arc::new(tokio::sync::Notify::new());
        let mock = Router::new()
            .route(
                "/v1/oauth2/device_authorization",
                post(|| async {
                    Json(serde_json::json!({"deviceCode": "DC", "userCode": "ABCDE", "verificationUriComplete": "link.tidal.com/ABCDE", "expiresIn": 300, "interval": 1}))
                }),
            )
            .route(
                "/v1/oauth2/token",
                post({
                    let (asked, go) = (asked.clone(), go.clone());
                    move || {
                        let (asked, go) = (asked.clone(), go.clone());
                        async move {
                            // Approved only once the test has signed out or removed the person
                            asked.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                            go.notified().await;
                            Json(serde_json::json!({"access_token": "AT", "refresh_token": "RT", "expires_in": 3600}))
                        }
                    }
                }),
            )
            .route(
                "/v1/sessions",
                get(|| async { Json(serde_json::json!({"userId": 42, "countryCode": "CH", "sessionId": "sid"})) }),
            );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://127.0.0.1:{}", listener.local_addr().unwrap().port());
        tokio::spawn(async move { axum::serve(listener, mock).await.unwrap() });
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, _) = two_people_node(dir.path(), &base).await;
        s.tidal.write().unwrap().v1_base = format!("{base}/v1");
        let app = router(s.clone());
        let owner = Some("s3cret");
        let (st, r, _) = send_as(
            &app,
            "PUT",
            "/v1/sources/tidal/unofficial",
            owner,
            &[],
            Some(serde_json::json!({"client_id": "dev-id", "client_secret": "dev-secret"})),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{r}");
        // Until TIDAL has been asked `n` times in all (it then waits for `go`)
        let asked_times = |n: u32| {
            let asked = asked.clone();
            async move {
                for _ in 0..200 {
                    if asked.load(std::sync::atomic::Ordering::SeqCst) >= n {
                        return;
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(25)).await;
                }
                panic!("TIDAL was never asked");
            }
        };
        let login = "/v1/sources/tidal/unofficial/login";

        // The owner signs out while TIDAL is asked
        let (st, r, _) = send_as(&app, "POST", login, owner, &[], None).await;
        assert_eq!(st, StatusCode::OK, "{r}");
        asked_times(1).await;
        let (st, _, _) = send_as(&app, "DELETE", login, owner, &[], None).await;
        assert_eq!(st, StatusCode::OK);
        go.notify_one();
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        let (_, r, _) = send_as(&app, "GET", "/v1/sources/tidal/unofficial", owner, &[], None).await;
        assert_eq!(r["signed_in"], false, "{r}");

        // A listener removed while TIDAL is asked
        let anna_tok = accounts::mint(&s, anna).unwrap();
        let (st, r, _) = send_as(&app, "POST", login, Some(&anna_tok), &[], None).await;
        assert_eq!(st, StatusCode::OK, "{r}");
        asked_times(2).await;
        let (st, r, _) = send_as(&app, "DELETE", &format!("/v1/people/{anna}"), owner, &[], None).await;
        assert_eq!(st, StatusCode::OK, "{r}");
        go.notify_one();
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        let rows = s
            .library
            .lock()
            .unwrap()
            .settings_with_prefix(&format!("person.{anna}."))
            .unwrap();
        assert!(rows.is_empty(), "{rows:?}");
        // Any other write for them lands nowhere either (a token refresh, an OAuth answer)
        let lib = s.library.lock().unwrap();
        let them = accounts::Who::Listener(anna.to_string());
        assert!(them.put(&lib, "tidal.user", Some("{}")).is_err());
        assert!(them.get(&lib, "tidal.user").is_none());
        assert!(
            them.put(&lib, "tidal.user", None).is_ok(),
            "removing stays allowed"
        );
    }

    /// Restoring a sealed backup restores each listener's sign-in from it, and keeps one made
    /// here that the backup doesn't have, as for the owner's (per-person follow-up, Kimi M2).
    #[tokio::test]
    async fn a_sealed_restore_keeps_listeners_sign_ins_it_does_not_have() {
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, ben) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let (locked, _) = backup::make(&s, Some("correct horse")).unwrap();
        {
            let lib = s.library.lock().unwrap();
            lib.set_setting(&format!("person.{anna}.tidal.user"), "anna-later")
                .unwrap();
            lib.set_setting(&format!("person.{ben}.tidal.user"), "ben-here")
                .unwrap();
        }
        backup::restore(&s, locked, Some("correct horse".into()), false)
            .await
            .unwrap();
        let lib = s.library.lock().unwrap();
        let row = |k: &str| lib.get_setting(&format!("person.{k}.tidal.user")).unwrap();
        assert!(row(anna).unwrap().contains("anna-token"), "from the backup");
        assert_eq!(
            row(ben).as_deref(),
            Some("ben-here"),
            "made here, not in the backup"
        );
    }

    /// Removing a listener also drops what was fetched with their sign-ins: TIDAL tracks kept for
    /// their browser, their search answers and item pages; the owner's stay (per-person
    /// follow-up, Kimi M3).
    #[tokio::test]
    async fn removing_a_listener_drops_what_was_fetched_for_them() {
        let dir = tempfile::tempdir().unwrap();
        let (s, anna, _) = two_people_node(dir.path(), "http://127.0.0.1:9").await;
        let app = router(s.clone());
        let at = std::time::Instant::now();
        tidal::keep_stream(
            &mut tidal::stream_cache().lock().unwrap(),
            (format!("{anna}/9990001"), at, vec![1].into(), "audio/mp4".into()),
        );
        {
            let mut a = s.search_answers.lock().unwrap();
            a.insert(
                ("lucky".into(), format!("tidal|{anna}")),
                (at, Default::default()),
            );
            a.insert(("lucky".into(), "tidal".into()), (at, Default::default()));
            let lib = s.library.lock().unwrap();
            lib.set_setting(&format!("item.contents.{anna}.tidal:album:1"), "[1,{}]")
                .unwrap();
            lib.set_setting("item.contents.tidal:album:1", "[1,{}]").unwrap();
        }
        let (st, r, _) = send_as(
            &app,
            "DELETE",
            &format!("/v1/people/{anna}"),
            Some("s3cret"),
            &[],
            None,
        )
        .await;
        assert_eq!(st, StatusCode::OK, "{r}");
        assert!(!tidal::stream_cache()
            .lock()
            .unwrap()
            .iter()
            .any(|(k, _, _, _)| *k == format!("{anna}/9990001")));
        let keys: Vec<String> = s
            .search_answers
            .lock()
            .unwrap()
            .keys()
            .map(|k| k.1.clone())
            .collect();
        assert_eq!(keys, ["tidal"], "{keys:?}");
        let lib = s.library.lock().unwrap();
        assert!(lib
            .settings_with_prefix(&format!("item.contents.{anna}."))
            .unwrap()
            .is_empty());
        assert!(lib.get_setting("item.contents.tidal:album:1").unwrap().is_some());
    }

