        assert!(r.invites.is_empty());
        let tok = accounts::mint(&s, ROSTER_KEY).unwrap();
        let (st, _) = as_who(&app, "GET", "/v1/library/tracks".into(), &tok, None).await;
        assert_eq!(st, StatusCode::UNAUTHORIZED);
